"""R07 §7 / §0.1 item 2: every report table is generated here from persisted files (never typed). Writes
R07/tables/*.md with a provenance comment naming the source file and keys, plus tables/sources.json."""
from __future__ import annotations
import glob, json, os, sys
import numpy as np, pandas as pd
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import r07_common as R7
REP = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); TAB = f"{REP}/tables"; os.makedirs(TAB, exist_ok=True)
SRC = {}
def emit(name, src, lines): SRC[name] = src; open(f"{TAB}/{name}.md", "w").write(f"<!-- generated by report_tables_r07.py from {src} -->\n" + "\n".join(lines) + "\n"); print(f"wrote tables/{name}.md")
def f(x, d=3): return "—" if x is None or (isinstance(x, float) and not np.isfinite(x)) else (f"{x:,}" if isinstance(x, (int, np.integer)) else f"{x:.{d}f}")

# 1. pretraining data (§1.1-1.3)
man = json.load(open(f"{R7.CACHE}/cache_manifest.json")); pb = pd.read_csv(f"{R7.CACHE}/per_bin.csv"); hold = json.load(open(f"{R7.CACHE}/heldout_cruises.json"))
c = man["counts"]
emit("pretraining_blocks", "cache/cache_manifest.json:counts", ["| item | blocks |", "|---|---|", f"| corpus | {c['corpus_blocks']:,} ({c['corpus_cruises']} cruises) |", f"| excluded: cell < 10 m | {c['excluded_cell_below_10m']:,} |", f"| excluded: cell > 256 m | {c['excluded_cell_above_256m']:,} |",
      f"| **reconstruction task** (10–256 m) | **{c['reconstruction_task_blocks']:,}** ({c['cruises_in_range']} cruises) |", f"| **sounding-spread task** (usable products) | **{c['spread_task_blocks']:,}** |", f"| held-out cruises / blocks (§1.3) | {hold['n_cruises']} / {hold['n_blocks']:,} |"])
L = ["| bin | cell (m) | blocks | train | held-out | usable | cruises | training windows built | share |", "|---|---|---|---|---|---|---|---|---|"]
for r in pb.itertuples(): L.append(f"| {r.bin} | {r.cell_lo_m:.1f}–{r.cell_hi_m:.1f} | {r.blocks:,} | {r.blocks_train:,} | {r.blocks_heldout:,} | {r.blocks_usable:,} | {r.cruises} | {int(r.train_windows_built):,} | {r.train_windows_share:.3f} |")
L.append(f"| all | 10–256 | {pb.blocks.sum():,} | {pb.blocks_train.sum():,} | {pb.blocks_heldout.sum():,} | {pb.blocks_usable.sum():,} | {c['cruises_in_range']} | {int(pb.train_windows_built.sum()):,} | 1.000 |")
emit("pretraining_bins", "cache/per_bin.csv (build_cache_r07.py)", L)
emit("heldout_cruises", "cache/heldout_cruises.json", ["| family | corpus cruises | held out | cruises |", "|---|---|---|---|"] + [f"| {fam} | {hold['family_cruise_counts'][fam]} | {len(cr)} | {', '.join(cr)} |" for fam, cr in hold["by_family"].items()])
tr, va = man["train"], man["val"]; st = man["rsd_log10_standardisation"]
emit("cache_summary", "cache/cache_manifest.json:train,val,rsd_log10_standardisation", ["| item | train | held-out |", "|---|---|---|", f"| windows drawn | {tr['n_drawn']:,} | {va['n_drawn']:,} |", f"| windows built | {tr['n_built']:,} | {va['n_built']:,} |", f"| dropped (ledger) | {tr['n_dropped']:,} | {va['n_dropped']:,} |",
      f"| shards | {tr['n_shards']} | {va['n_shards']} |", f"| size | {tr['bytes']/1e9:.1f} GB | {va['bytes']/1e9:.2f} GB |", f"| log10 ship_rsd standardisation (train covered blocks) | mean {st['mean']:.3f}, SD {st['sd']:.3f}, n {st['n_blocks']:,} | |"])

# 2. pilot and pretext results (§2.3-2.4)
def eval_table(body, d):
    ev = json.load(open(f"{R7.PRETRAIN}/{d}/eval.json")); L = ["| step | held-out windows | recon MSE (masked px) | mean-fill baseline MSE | recon / baseline | spread MSE (std units) | covered blocks | Spearman ρ (blocks) | within-window ρ (median) |", "|---|---|---|---|---|---|---|---|---|"]
    for s in sorted(ev, key=int): e = ev[s]; L.append(f"| {int(s):,} | {e['n_windows']:,} | {e['recon_mse_masked_px']:.4f} | {e['baseline_meanfill_mse_masked_px']:.4f} | {e['recon_over_baseline']:.3f} | {e['spread_mse_std']:.4f} | {e['n_covered_blocks']:,} | {f(e['spread_rho_blocks'])} | {f(e['spread_rho_within_window_median'])} |")
    return L
if os.path.exists(f"{R7.PRETRAIN}/P-V1_pilot/eval.json"):
    pl = json.load(open(f"{R7.PRETRAIN}/P-V1_pilot/pretrain_log.json")); r = pl["pilot_rule"]
    emit("pilot", "pretrain/P-V1_pilot/eval.json, pretrain_log.json:pilot_rule", eval_table("P-V1", "P-V1_pilot") + ["", f"Wall time {pl['wall_train_s']/60:.1f} min for {pl['steps']:,} steps ({pl['s_per_step']:.3f} s/step) on {pl['gpu']}; rule: recon {r['recon_step0']:.4f} → {r['recon_final']:.4f}, spread {r['spread_step0']:.4f} → {r['spread_final']:.4f}: **{r['verdict']}**."])
for body in R7.BODIES:
    if os.path.exists(f"{R7.PRETRAIN}/{body}/eval.json"):
        pl = json.load(open(f"{R7.PRETRAIN}/{body}/pretrain_log.json")); cv = json.load(open(f"{R7.PRETRAIN}/{body}/curves.json"))["curves"]
        L = eval_table(body, body) + ["", f"Training: {pl['steps']:,} steps, {pl['wall_train_s']/3600:.2f} h ({pl['s_per_step']:.3f} s/step) on {pl['gpu']}; params {pl['params']:,} (body {pl['params_body']:,}, branch {pl['params_branch']:,}).", "",
             "| step | train recon (100-step mean) | train spread | lr |", "|---|---|---|---|"] + [f"| {x['step']:,} | {x['recon']:.4f} | {x['spread']:.4f} | {x['lr']:.2e} |" for x in cv if x["step"] % 5000 == 0 or x["step"] == cv[-1]["step"]]
        emit(f"pretext_{body}", f"pretrain/{body}/eval.json, curves.json, pretrain_log.json", L)

# 3. equivalence checks (§1.4, §3.3)
eq = json.load(open(f"{R7.CHECKS}/equiv_windows.json")); L = ["| check | result |", "|---|---|", f"| §1.4 windows identical to the stored R06 input arrays | {eq['n_identical_to_stored_r06_arrays']} / {eq['n']} |", f"| §1.4 windows identical to the recomputed R06 builder | {eq['n_identical_to_recomputed_r06_builder']} / {eq['n']} |", f"| §1.4 windows on product-usable pairs (V2 channels + masks checked) / pairs covered | {eq['n_usable_windows']} / {eq['n_pairs']} |"]
if os.path.exists(f"{R7.CHECKS}/scratch_equiv/result.json"):
    se = json.load(open(f"{R7.CHECKS}/scratch_equiv/result.json"))
    L += [f"| §3.3 predictions identical (V1 / lu00 / 20261002, {se['n_windows']:,} windows) | {se['predictions_identical']} (max abs diff log10 blocks {se['max_abs_diff_blocks_log10']:.2e}; tile {se['max_abs_diff_tile_m']:.2e} m) |", f"| §3.3 weights identical | {se['weights_identical']} (max abs diff {se['weights_max_abs_diff']:.2e}) |",
          f"| §3.3 GPU this run / R06 | {se['gpu_this_run']} / {se['gpu_r06']} (hosts {se['host_this_run']} / {se['host_r06']}) |", f"| §3.3 final 100-step train loss this / R06 | {se['final_loss_100_this']:.6f} / {se['final_loss_100_r06']:.6f} |"]
emit("equivalence", "checks/equiv_windows.json, checks/scratch_equiv/result.json", L)

# 4. compute (§6)
if os.path.exists(f"{R7.ROOT}/compute_estimate.json"):
    ce = json.load(open(f"{R7.ROOT}/compute_estimate.json")); L = ["| item | GPU-h |", "|---|---|", f"| already used (pilot, §3.3 test) | {sum(ce['already_used_gpu_h'].values()):.1f} |"] + [f"| pretraining {k} (60,000 steps) | {v:.1f} |" for k, v in ce["pretraining_gpu_h"].items()] + [f"| fine-tuning {k} ({v['n']} trainings, 1.5× A100 allowance) | {v['gpu_h']:.1f} |" for k, v in ce["finetuning_gpu_h"].items()] + [f"| **estimate** | **{ce['gpu_h_estimate']:.1f}** of {ce['budget_gpu_h']:.0f} ({'within' if ce['within_budget'] else 'EXCEEDS'} budget) |"]
    emit("compute_estimate", "compute_estimate.json", L)
if os.path.exists(f"{R7.SCORES}/compute_summary.json"):
    cs = json.load(open(f"{R7.SCORES}/compute_summary.json")); L = ["| item | trainings | GPU-h |", "|---|---|---|"] + [f"| fine-tuning {a} (median {d['s_per_step']:.3f} s/step) | {d['n']} | {d['gpu_h']:.1f} |" for a, d in cs["by_arm"].items()] + [f"| pretraining {p['body']}{' pilot' if p['pilot'] else ''} ({p['steps']:,} steps, {p['gpu']}) | 1 | {p['gpu_h']:.1f} |" for p in cs["pretrain"]] + [f"| §3.3 scratch-equivalence test | 1 | {cs['gpu_h_checks']:.1f} |", f"| **total** | | **{cs['gpu_h_total']:.1f}** of {cs['budget_gpu_h']:.0f} |", "", "| GPU | trainings | GPU-h |", "|---|---|---|"] + [f"| {g} | {d['n']} | {d['gpu_h']:.1f} |" for g, d in cs["by_gpu"].items()]
    emit("compute_used", "scores/compute_summary.json", L)

# 5. ledger of skipped / failed / requeued items
L = ["| stage | item | count | reason |", "|---|---|---|---|"]
led = pd.read_csv(f"{R7.CACHE}/ledger.csv") if os.path.exists(f"{R7.CACHE}/ledger.csv") else pd.DataFrame(columns=["reason"])
if len(led): L += [f"| cache | dropped windows | {int(n)} | {r} |" for r, n in led.reason.value_counts().items()]
else: L.append("| cache | dropped windows | 0 | — |")
if os.path.exists(f"{R7.ROOT}/task_ledger.json"):
    for r in json.load(open(f"{R7.ROOT}/task_ledger.json")): L.append(f"| {r['stage']} | {r['item']} | {r['count']} | {r['reason']} |")
emit("ledger", "cache/ledger.csv, task_ledger.json (sacct)", L)
json.dump(SRC, open(f"{TAB}/sources.json", "w"), indent=1)
